-- BASES DE LA GIRA JUNIOR CLASSIC 2026-2027
-- Comité Infantil Juvenil Zona Norte (ACGN)
-- Fuente: PDF oficial "Bases de la Gira Junior Classic 2026-2027".
-- Base de datos: golftour  ·  Tabla: convocatoria_content
-- Idempotente vía ON DUPLICATE KEY UPDATE (torneoid, section_id).
-- =====================================================================

START TRANSACTION;

-- ---------------------------------------------------------------------
-- 1. Descripción general (objetivo, vigencia, cupo, constitución, etapas)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'descripcion', 'generic', 'Objetivo y vigencia', '{"text": "GIRA JUNIOR CLASSIC 2026-2027 — Comité Infantil Juvenil Zona Norte (ACGN).\\n\\nOBJETIVO: dar a conocer las bases de competencia de la Gira Junior Classic y el criterio de elegibilidad para los aspirantes a participar, así como fomentar, desarrollar y apoyar al golf infantil-juvenil cimentando los valores del golf: puntualidad, honestidad, respeto, responsabilidad y cortesía.\\n\\nVIGENCIA: de octubre 2026 a mayo 2027.\\n\\nCUPO MÁXIMO: 220 jugadores.\\n\\nFECHAS DE LAS ETAPAS:\\nEtapa I — Club Campestre Monterrey — 4 de octubre, 2026\\nEtapa II — Las Aves — 31 de octubre y 1 de noviembre, 2026\\nEtapa III — Herradura / Misiones — 13 de diciembre, 2026\\nEtapa IV — Terralta — 17 de enero, 2027\\nEtapa V — Campestre Saltillo — 21 de febrero, 2027\\nEtapa VI — Herradura / Valle Alto — 11 de abril, 2027\\n(Etapa por confirmar.)\\n\\nINAUGURACIÓN: 4 de octubre de 2026 en el Club Campestre Monterrey A.C. (hora por confirmar). La asistencia es obligatoria para los jugadores que no tengan su salida en ese horario; cada jugador deberá portar la playera del color de su club y el banderín representativo en el desfile de clubes. El uso del uniforme del club es obligatorio a partir de la segunda etapa."}', 1, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

-- ---------------------------------------------------------------------
-- 2. Elegibilidad, inscripción y registro
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'elegibilidad', 'generic', 'Elegibilidad e inscripción', '{"eligibilityText": "Serán elegibles los jugadores de rama varonil y femenil que estén en el inicio del desarrollo de sus habilidades en este deporte. Se jugarán 5 categorías por rama: 7 años y menores, 8-9 años, 10-11 años, 12-13 años y 14-18 años. La fecha de corte que determina la categoría del jugador(a) serán años cumplidos al 12 de abril de 2027.", "notesText": ["Los clubes sede tienen derecho a inscribir 28 jugadores cada uno. Se sugiere dar espacio primero a los jugadores que se inscribieron en la Gira Zona Norte y no calificaron.", "Si un jugador de los 28 elegidos no puede participar en alguna etapa, puede ser sustituido por otro jugador de su club de la misma categoría, pagando la etapa individual de $2,000.00. Ese jugador no suma puntos para las Copas por equipos ni participa en el Ranking Individual.", "Registro en la página de ACGN (jr@golftour.mx): solo los jugadores autorizados por su club que aparezcan en la lista de la Gira Junior Classic.", "Los listados deben ser enviados por el profesional del club antes del 15 de septiembre de 2026 a Carlos Carranza (carlos.carranza@acgn.com.mx) con: nombre, apellido, club, categoría, fecha de nacimiento y contacto.", "Registro para clubes sede: del 17 al 18 de septiembre de 2026, de 10:00 a 18:00 hrs.", "Registro para jugadores que no pertenecen a club sede: del 22 al 23 de septiembre de 2026, de 10:00 a 17:00 hrs.", "Los comprobantes de pago deben subirse al sistema al momento del registro.", "Cierre de inscripciones y recepción de pagos: 23 de septiembre de 2026, o hasta alcanzar el cupo de 220 jugadores, lo que ocurra primero.", "Después del cierre solo se aceptan inscripciones por etapa (Etapas II a VI), sujetas a disponibilidad, con costo de $2,000.00 por etapa.", "Los jugadores que participen en la Gira Infantil Juvenil Zona Norte NO podrán integrarse a la Gira Junior Classic: ningún jugador puede participar en 2 giras al mismo tiempo.", "Los jugadores confirman su participación a cada etapa a través de los profesionales de su club, 8 días antes de la etapa.", "Se sancionará a los jugadores confirmados que no se presenten a jugar: su participación en la siguiente etapa queda sujeta a disponibilidad y se les descuentan 30 puntos por etapa no cancelada en la Copa Challenge y en el Ranking."], "inscripcionesText": "Registro en línea: jr@golftour.mx · Autorizaciones y listados: Carlos Carranza — carlos.carranza@acgn.com.mx"}', 2, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

-- ---------------------------------------------------------------------
-- 3. Costos de inscripción y datos bancarios
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'costos', 'generic', 'Costos de inscripción', '{"sociosPricing": [{"title": "Gira completa (6 etapas)", "caballeros": "$7,600.00", "damasSeniors": "$7,600.00"}, {"title": "Hijos de profesionales de golf", "caballeros": "$2,000.00", "damasSeniors": "$2,000.00"}], "foraneosPricing": [{"title": "Inscripción por etapa (Etapas II a VI)", "caballeros": "$2,000.00", "damasSeniors": "$2,000.00"}], "pricingNote": "El costo de la Gira completa es de $7,600.00 (siete mil seiscientos pesos 00/100 M.N.) en una sola exhibición y ampara las 6 etapas. Los hijos de profesionales de golf pagan una cuota especial de $2,000.00 y deben ser autorizados por Carlos Carranza (carlos.carranza@acgn.com.mx). La inscripción por etapa cuesta $2,000.00 y está sujeta a disponibilidad.", "contactInfo": {"bankName": "Banorte", "clabe": "072580008350015208", "cuenta": "0835001520", "nombre": "Asociación de Clubes de Golf del Norte A.C.", "email": "carlos.carranza@acgn.com.mx", "telefono": "", "telefonoDirecto": ""}, "contactWarning": "Los comprobantes de pago deben subirse al sistema al momento del registro. Cierre de inscripciones y pagos: 23 de septiembre de 2026.", "inscripcionesText": "Depósitos y transferencias a nombre de ACGN Junior Classic — Asociación de Clubes de Golf del Norte A.C.\\nBanco: Banorte · Cuenta: 0835001520 · CLABE: 072580008350015208"}', 3, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

-- ---------------------------------------------------------------------
-- 4. Sistema de juego, distancias, facilidades y ranking
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'reglas', 'list', 'Reglas y sistema de juego', '{"items": [{"titulo": "Sistema de juego", "descripcion": "Se juega por categorías bajo la modalidad de juego por golpes (stroke play). La Gira consta de 6 etapas, debiendo jugarse un mínimo de cuatro para tener derecho al Ranking Regional. Cada etapa es de 9 hoyos en todas las categorías y en ambas ramas."}, {"titulo": "Etapas oficiales", "descripcion": "Una etapa se considera oficial si todos los jugadores de la categoría juegan al menos 5 hoyos. Si no se cumplen los 5 hoyos, la etapa se considera incompleta y no cuenta para el Ranking Individual ni por Equipos."}, {"titulo": "Distancias — Femenil", "descripcion": "7 y menores: marcas modificadas, par 36, 1,000 yardas, 9 hoyos. 8-9: modificadas, par 36, 1,400 yardas. 10-11: modificadas, par 36, 1,800 yardas. 12-13: modificadas, par 36, 2,000 yardas. 14-18: marcas rojas, par 36, 2,200 yardas."}, {"titulo": "Distancias — Varonil", "descripcion": "7 y menores: marcas modificadas, par 36, 1,000 yardas, 9 hoyos. 8-9: modificadas, par 36, 1,400 yardas. 10-11: modificadas, par 36, 2,000 yardas. 12-13: marcas rojas, par 36, 2,400 yardas. 14-18: marcas blancas, par 36, 3,200 yardas."}, {"titulo": "Facilidades de los jugadores", "descripcion": "Todos los jugadores deberán llevar caddie. Se puede usar carrito de remolcar y carritos de golf en los clubes que cuenten con ese servicio."}, {"titulo": "Reglas de juego", "descripcion": "Se aplicarán las reglas de la USGA y las locales del club sede, aprobadas por el Comité Organizador. Para todas las categorías habrá un máximo de 10 golpes por hoyo."}, {"titulo": "Conductas sancionables", "descripcion": "Camisas sin cuello no diseñadas para golf (ambas ramas); camisas sin manga en varonil; uso de mezclilla; spikes metálicos; radios, celulares y equipos de intercomunicación; maltratar el campo o no reparar divots y trampas; lenguaje obsceno; gestos o señas vulgares y cualquier agresión; fumar cualquier tipo de cigarrillo, incluidos electrónicos o de vapor."}, {"titulo": "Sanciones", "descripcion": "Según la gravedad de la infracción: amonestación, dos golpes de castigo, descalificación de la etapa donde ocurra la infracción o expulsión de la Gira."}, {"titulo": "Jueces y uniformes", "descripcion": "El comité de golf y torneos emplea a los profesionales de los clubes inscritos a ACGN como jueces de campo. Los Comités Infantiles Juveniles de cada club determinarán el uso de uniformes. La rama varonil deberá traer la camisa por dentro del pantalón o bermuda y portar la gorra hacia el frente."}, {"titulo": "Ranking Regional", "descripcion": "El Ranking Regional es anual: inicia en la Etapa I y concluye en la Etapa VI. Se requiere un mínimo de 4 etapas jugadas y se consideran las mejores 4 de las seis. Una descalificación por enfermedad o por infringir una regla cuenta como etapa jugada con cero puntos. Puntos por lugar: 1° 20.0, 2° 12.0, 3° 8.5, 4° 7.0, 5° 5.6, 6° 4.6, 7° 4.0, 8° 3.5, 9° 3.1, 10° 2.8."}]}', 4, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

-- ---------------------------------------------------------------------
-- 5. Desempates
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'desempates', 'desempates', 'Desempates', '{"intro": "Criterios de desempate de la Gira Junior Classic 2026-2027.", "showCorte": false, "showTrofeos": true, "paraCorte": [], "paraTrofeos": ["En caso de empate al 1er lugar de cada etapa, se decide a muerte súbita en el campo y los puntos de ranking se otorgan al ganador.", "Para empates del 2° lugar en adelante, el desempate es por sistema de retrogresión y los puntos de ranking se dividen entre el número de jugadores empatados.", "Los empates en los puntos del Ranking Regional se resuelven con base en el promedio de scores de los jugadores involucrados."], "nota": "El comité se reserva el derecho de efectuar los cambios necesarios a estas bases para lograr el mejor desarrollo de la Gira Junior Classic, siendo sus decisiones inapelables."}', 5, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

-- ---------------------------------------------------------------------
-- 6. Premiación (regalos y premios)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES (135, 'premiacion', 'list', 'Regalos y premios', '{"items": [{"categoria": "Cada etapa — Varonil", "premios": ["Trofeos del 1° al 5° lugar.", "Medalla al 6° y 7° lugar."]}, {"categoria": "Cada etapa — Femenil", "premios": ["Trofeos del 1° al 5° lugar.", "Medalla al 6° y 7° lugar."]}, {"categoria": "Fin de la Gira", "premios": ["Premio especial al 1er lugar del Ranking de cada categoría en ambas ramas.", "Copa Challenge al club con mayor cantidad de puntos en toda la temporada."]}, {"categoria": "Otros", "premios": ["Regalo de bienvenida a los participantes inscritos y con inscripción completa pagada conforme al punto 5.", "Rifa especial en cada etapa; es necesario estar presente para reclamar el premio."]}]}', 6, 1)
ON DUPLICATE KEY UPDATE section_type = VALUES(section_type), title = VALUES(title), content = VALUES(content), sort_order = VALUES(sort_order), enabled = 1;

COMMIT;
